(function($){

  // Reload email log table without reloading the page
  function reloadEmailLogTable() {
    var $form = $('#contactin-email-log-form');
    if (!$form.length) return;
    
    var formData = $form.serialize();
    
    $.post(ContactINEmailLog.ajax_url, {
      action: 'contactinbox_get_email_logs',
      nonce: ContactINEmailLog.nonce,
      paged: $form.find('input[name="paged"]').val() || 1,
      per_page: $form.find('select[name="per_page"]').val() || 20,
      status: $('#status-filter').val() || 'all',
      orderby: $form.find('input[name="orderby"]').val() || 'created_at',
      order: $form.find('input[name="order"]').val() || 'DESC'
    }, function(response) {
      if (response && response.success && response.data && response.data.html) {
        $('.wp-list-table-container').html(response.data.html);
      }
    });
  }

  // Busy helper for long actions
  function setBusy($btn, busy, label) {
    if (!$btn || !$btn.length) return;
    if (busy) {
      $btn.addClass('is-busy').prop('disabled', true);
      if (label) $btn.data('orig-label', $btn.text()).text(label);
    } else {
      $btn.removeClass('is-busy').prop('disabled', false);
      if ($btn.data('orig-label')) {
        $btn.text($btn.data('orig-label'));
        $btn.removeData('orig-label');
      }
    }
  }

  // Utility: render meta block without showing internal id
  function renderMeta(d) {
    var html = '';
    html += '<p><strong>Timestamp:</strong> ' + (d.timestamp || '') + '</p>';
    html += '<p><strong>Recipient:</strong> ' + (d.recipient || '') + '</p>';
    html += '<p><strong>Subject:</strong> ' + (d.subject || '') + '</p>';
    html += '<p><strong>Status:</strong> ' + (d.status || '') + '</p>';
    if (d.error) {
      html += '<p><strong>Error:</strong> ' + d.error + '</p>';
    }
    return html;
  }

  // Utility: populate modal with log data
  function populateModal(d) {
    $('#contactin-email-meta').html(renderMeta(d)).data('log-id', d.id);
      $('#contactin-email-headers').text(d.headers || ContactINEmailLog.i18n.noDetails || 'No details');
    $('#contactin-email-body').text(d.body || ContactINEmailLog.i18n.noDetails || 'No details');
  }

  // Utility: enable/disable navigation buttons
  function updateNavButtons(hasPrev, hasNext) {
    $('#contactin-prev-log').prop('disabled', !hasPrev);
    $('#contactin-next-log').prop('disabled', !hasNext);
  }

  // Fallback: probe adjacency silently if server didn't return hasPrev/hasNext
  function probeAdjacency(currentId) {
    var prevReq = $.post(ContactINEmailLog.ajax_url, {
      action: 'contactin_get_adjacent_email_log',
      direction: 'prev',
      current_id: currentId,
      nonce: ContactINEmailLog.nonce
    });

    var nextReq = $.post(ContactINEmailLog.ajax_url, {
      action: 'contactin_get_adjacent_email_log',
      direction: 'next',
      current_id: currentId,
      nonce: ContactINEmailLog.nonce
    });

    $.when(prevReq, nextReq).done(function(prevResp, nextResp) {
      var hasPrev = prevResp[0] && prevResp[0].success === true;
      var hasNext = nextResp[0] && nextResp[0].success === true;
      updateNavButtons(hasPrev, hasNext);
    }).fail(function() {
      updateNavButtons(true, true);
    });
  }

  // Prune old Email logs
  $('#contactin-prune-email-btn').on('click', function(e){
    e.preventDefault();
    var $btn = $(this);

    var days = ContactINEmailLog.retention_days || 90;
    var msg = ContactINEmailLog.i18n.confirmPrune 
      || ('This will permanently delete all email logs older than ' + days + ' days. This cannot be undone. Proceed?');

    if(!confirm(msg)) return;

    setBusy($btn, true, ContactINEmailLog.i18n?.working || 'Working...');

    $.post(ContactINEmailLog.ajax_url, {
      action: 'contactin_prune_email_logs',
      nonce: ContactINEmailLog.nonce
    })
    .done(function(response){
      if(response && response.success){
        cinShowMessage(response.data && response.data.message ? response.data.message : ContactINEmailLog.i18n.pruning, 'success');
        setBusy($btn, false);
        setTimeout(function() {
          reloadEmailLogTable();
        }, 1500);
      } else {
        cinShowMessage(response.data && response.data.message ? response.data.message : ContactINEmailLog.i18n.errorPrune, 'error');
        setBusy($btn, false);
      }
    })
    .fail(function(xhr){
      cinShowMessage(ContactINEmailLog.i18n.network_error + ' (' + xhr.status + ')', 'error');
      setBusy($btn, false);
    });
  });

  // Clear All Email Logs
  $('#contactin-clear-email-logs').on('click', function(e){
    e.preventDefault();

    var msg = ContactINEmailLog.i18n.confirmClearAll 
      || 'Are you sure you want to CLEAR ALL email logs? This will permanently delete all email logs and cannot be undone.';

    if(!confirm(msg)) return;

    var $btn = $(this);

    setBusy($btn, true, ContactINEmailLog.i18n?.working || 'Working...');

    $.ajax({
      url: ContactINEmailLog.ajax_url,
      method: 'POST',
      data: {
        action: 'contactin_email_clear_all_logs',
        _ajax_nonce: ContactINEmailLog.clear_all_nonce
      },
      dataType: 'json'
    })
    .done(function(response){
      if(response && response.success){
        cinShowMessage(response.data && response.data.message ? response.data.message : 'All email logs cleared.', 'success');
        setBusy($btn, false);
        setTimeout(function() {
          reloadEmailLogTable();
        }, 1500);
      } else {
        cinShowMessage(response.data && response.data.message ? response.data.message : 'Failed to clear email logs.', 'error');
        setBusy($btn, false);
      }
    })
    .fail(function(xhr){
      cinShowMessage(ContactINEmailLog.i18n.network_error + ' (' + xhr.status + ')', 'error');
      setBusy($btn, false);
    });
  });

  // Download Email Logs CSV
  $(document).on('click', '.cin-download-csv', function(e){
    e.preventDefault();
    var $btn = $(this);
    var baseUrl = ContactINEmailLog.ajax_url + '?action=contactinbox_download_email_csv&_wpnonce=' + encodeURIComponent(ContactINEmailLog.nonce);
    var status  = $('#status-filter').val() || 'all';

    if (typeof window.cinExportHelper === 'function') {
      window.cinExportHelper({
        infoAction: 'contactinbox_email_export_info',
        baseUrl: baseUrl,
        status: status
      });
    } else {
      // Fallback: direct download
      window.location.href = baseUrl;
    }
  });

  // View details modal
  $(document).on('click', '.contactin-view-email', function(){
    var id = $(this).data('id');
    if(!id) return;

    $('#contactin-email-meta').empty();
    $('#contactin-email-headers').text(ContactINEmailLog.i18n.loadingHeaders || 'Loading headers…');
    $('#contactin-email-body').text(ContactINEmailLog.i18n.loadingBody || 'Loading body…');

    $.post(ContactINEmailLog.ajax_url, {
      action: 'contactin_get_email_log',
      id: id,
      nonce: ContactINEmailLog.nonce
    })
    .done(function(response){
      if(response && response.success){
        var d = response.data;
        populateModal(d);
        $('#contactin-email-modal').addClass('is-active');

        if (typeof d.hasPrev !== 'undefined' && typeof d.hasNext !== 'undefined') {
          updateNavButtons(!!d.hasPrev, !!d.hasNext);
        } else {
          probeAdjacency(d.id);
        }
      } else {
        $('#contactin-email-meta').html(response.data && response.data.message ? response.data.message : ContactINEmailLog.i18n.errorDetails);
      }
    })
    .fail(function(){
      $('#contactin-email-meta').html(ContactINEmailLog.i18n.network_error);
    });
  });

  // Close modal
  $(document).on('click', '.contactin-modal-backdrop', function(){
    $('#contactin-email-modal').removeClass('is-active');
  });

  // Prev/Next navigation
  $('#contactin-prev-log').on('click', function(){ navigateAdjacentEmail('prev'); });
  $('#contactin-next-log').on('click', function(){ navigateAdjacentEmail('next'); });

  function navigateAdjacentEmail(direction){
    var currentId = $('#contactin-email-meta').data('log-id');
    if(!currentId) return;

    $.post(ContactINEmailLog.ajax_url, {
      action: 'contactin_get_adjacent_email_log',
      direction: direction,
      current_id: currentId,
      nonce: ContactINEmailLog.nonce
    })
    .done(function(response){
      if(response && response.success){
        var d = response.data;
        populateModal(d);
        if (typeof d.hasPrev !== 'undefined' && typeof d.hasNext !== 'undefined') {
          updateNavButtons(!!d.hasPrev, !!d.hasNext);
        } else {
          updateNavButtons(true, true);
        }
      } else {
        updateNavButtons(direction === 'prev' ? false : true, direction === 'next' ? false : true);
      }
    })
    .fail(function(){
      cinShowMessage(ContactINEmailLog.i18n.network_error, 'error');
    });
  }

  // Apply filter and refresh table
  $('#filter-submit').on('click', function(e){
    e.preventDefault();

    $.post(ContactINEmailLog.ajax_url, {
      action: 'contactin_get_email_logs',
      nonce: ContactINEmailLog.nonce,
      status: $('#status-filter').val(),
      orderby: $('input[name="orderby"]').val() || 'created_at',
      order: $('input[name="order"]').val() || 'DESC',
      limit: 20,
      offset: 0
    })
    .done(function(response){
      var $tbody = $('#the-list');
      $tbody.empty();

      if(response && response.success){
        var rows = response.data.rows || [];
        if(rows.length === 0){
          $tbody.append(
            '<tr class="no-items"><td class="colspanchange" colspan="5">'
            + (response.data.message || 'No email logs found.')
            + '</td></tr>'
          );
        } else {
          rows.forEach(function(row){
            $tbody.append(
              '<tr>' +
                '<td>' + (row.created_at || '') + '</td>' +
                '<td>' + (row.recipient || '') + '</td>' +
                '<td>' + (row.subject || '') + '</td>' +
                '<td>' + (row.status || '') + '</td>' +
                '<td>' + (row.error_message || '') + '</td>' +
              '</tr>'
            );
          });
        }
      } else {
        $tbody.append(
          '<tr class="no-items"><td class="colspanchange" colspan="5">'
          + ((response.data && response.data.message) || 'Failed to load logs.')
          + '</td></tr>'
        );
      }
    })
    .fail(function(xhr){
      var $tbody = $('#the-list');
      $tbody.empty().append(
        '<tr class="no-items"><td class="colspanchange" colspan="5">'
        + ContactINEmailLog.i18n.network_error + ' (' + xhr.status + ')'
        + '</td></tr>'
      );
    });
  });

  // Handle per-page dropdown auto-submit
  $(document).on('change', '.cin-per-page-select', function() {
    var url = new URL(window.location.href);
    var per_page = $(this).val();
    url.searchParams.set('per_page', per_page);
    url.searchParams.set('paged', '1'); // Reset to page 1 when per_page changes
    window.location.href = url.toString();
  });

})(jQuery);
